package com.mynote.android.util

import android.content.Context

/**
 * 疾病速查 — 三甲各科室常见病 | 核心症状 | 鉴别诊断 | 常用药物 | 治疗手段
 * 数据优先从 assets/diseases.json 加载，失败回退硬编码
 */
object DiseaseReference {

    data class Disease(
        val name: String,
        val department: String,
        val symptoms: String,
        val differential: String,
        val drugs: String,
        val treatment: String
    )

    @Volatile private var cached: List<Disease>? = null

    fun init(context: Context) {
        if (cached != null) return
        cached = JsonAssetLoader.loadList<Disease>(context.applicationContext, "diseases.json")
            ?: hardcoded()
    }

    fun getAll(): List<Disease> = cached ?: hardcoded()

